/* Generated by Balsa UI. Do not edit.
 *
 * Maps the active Balsa design system onto the standard shadcn token surface so
 * components installed from @shadcn (or any compatible registry) follow the
 * Balsa palette, radius and focus ring.
 *
 * Import after the Balsa foundation, theme and palette, and before any
 * stylesheet that intentionally overrides these variables.
 */

:root {
  --background: var(--color-balsa-background);
  --foreground: var(--color-balsa-foreground);
  --card: var(--color-balsa-surface);
  --card-foreground: var(--color-balsa-surface-foreground);
  --popover: var(--color-balsa-surface-elevated);
  --popover-foreground: var(--color-balsa-surface-elevated-foreground);
  --primary: var(--color-balsa-primary);
  --primary-foreground: var(--color-balsa-primary-foreground);
  --secondary: var(--color-balsa-secondary);
  --secondary-foreground: var(--color-balsa-secondary-foreground);
  --muted: var(--color-balsa-muted);
  --muted-foreground: var(--color-balsa-muted-foreground);
  --accent: var(--color-balsa-accent);
  --accent-foreground: var(--color-balsa-accent-foreground);
  --destructive: var(--color-balsa-destructive);
  --destructive-foreground: var(--color-balsa-destructive-foreground);
  --border: var(--color-balsa-border);
  --input: var(--color-balsa-input-border);
  --ring: var(--color-balsa-focus-ring);

  --chart-1: var(--color-balsa-primary);
  --chart-2: var(--color-balsa-secondary);
  --chart-3: var(--color-balsa-accent);
  --chart-4: var(--color-balsa-info);
  --chart-5: var(--color-balsa-success);

  --sidebar: var(--color-balsa-surface);
  --sidebar-foreground: var(--color-balsa-surface-foreground);
  --sidebar-primary: var(--color-balsa-primary);
  --sidebar-primary-foreground: var(--color-balsa-primary-foreground);
  --sidebar-accent: var(--color-balsa-selected);
  --sidebar-accent-foreground: var(--color-balsa-selected-foreground);
  --sidebar-border: var(--color-balsa-border);
  --sidebar-ring: var(--color-balsa-focus-ring);

  /* Upstream expects one base radius and derives the rest. */
  --radius: var(--balsa-radius-surface);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

/* The radius ramp is deliberately NOT declared in @theme inline.
 *
 * An inline theme value is substituted into the utility at build time, so
 * rounded-md would compile to border-radius: calc(var(--radius) - 2px) and stop
 * reading --radius-md altogether, which makes the per-token override below dead
 * code. Leaving Tailwind's own radius scale in place keeps rounded-md reading
 * var(--radius-md), so the adapter scope can map each step onto the Balsa ramp.
 */

/* Opt-in adapter scope.
 *
 * Upstream components spend shape, typography and motion through Tailwind's own
 * theme variables rather than through shadcn's semantic ones, so carrying those
 * dimensions means redefining Tailwind's variables. Those cascade to every
 * utility, including the consumer's own markup, so this is scoped rather than
 * applied at :root. Opt in where you want it:
 *
 *   <html data-balsa-adapt>          the whole application
 *   <div data-balsa-adapt>...</div>  one subtree
 *
 * Density, type scale, border width and elevation are deliberately absent; see
 * .balsa/design-system.json for why each one cannot be carried this way.
 */
[data-balsa-adapt] {
  --radius-sm: var(--balsa-radius-badge);
  --radius-md: var(--balsa-radius-control);
  --radius-lg: var(--balsa-radius-surface);
  --radius-xl: var(--balsa-radius-panel);
  --font-sans: var(--balsa-font-body);
  --font-weight-medium: var(--balsa-control-font-weight);
  --default-transition-duration: var(--balsa-motion-normal);
  --default-transition-timing-function: var(--balsa-motion-easing);
}
